Denote a sequence of $N$ transmitted
symbols by

 \begin{equation} S = (s_1,s_2,....s_N) \end{equation}

Here we treat the case of a {\it symmetric} process, i.e. $P_{+,-}
= P_{-,+}=p,~~$ so that we have

\begin{equation} s_{i+1} = \left\{  \begin{array}{ll}
                      ~~ s_i \qquad \qquad & {\rm prob.}= 1-p \\
                     -s_i \qquad \qquad & {\rm prob.}= p \end{array} \right.
\label{eq:Markov} \end{equation}

Once the underlying Markov process $S$ has been generated, the
probability of observing a particular sequence ${\it R }$ is given by

\begin{equation} Pr({\it R }|S) = \prod_{i=1}^N Pr(r_i|s_i) \label{eq:PSig} \end{equation}

and the joint probability of any particular $S$ and ${\it R }$ to occur
is given by

\begin{equation} Pr({\it R }, S) = Pr({\it R }|S)Pr(S) \label{eq:joint} \end{equation}

Furthermore, one is interested in the\footnote{The Shannon entropy
is defined using log$_2$; we use natural log for simplicity} {\it
Shannon entropy H} of the observed process,

\begin{equation} H_N = -\sum_{\it R } Q({\it R }) \log Q({\it R }) \label{eq:HN} \end{equation}

and in particular, in the {\it entropy rate}, defined as

\begin{equation} H = \lim_{N \rightarrow \infty} \frac{H_N}{N}\end{equation}

Substituting in (\ref{eq:HN}),  the entropy of
the process can be written as











\begin{equation}
H_N =  - \sum_{\it R } A~Z({\it R }) \log[A Z({\it R })]
    =  - \left[ \frac{d }{dn} \sum_{\it R } [A~Z({\it R })]^n
    \right]_{n=1}
\label{H_N_def} \end{equation}

\begin{equation}
H_N =  - \sum_{\it R } A~Z({\it R }) \log[A Z({\it R })]
    =  - \left[ \frac{d }{dn} \sum_{\it R } [A~Z({\it R })]^n
    \right]_{n=1}
\label{H_N_def} \end{equation}

We are interested in calculating the entropy rate

\begin{equation} H = - \lim_{N \rightarrow \infty}\left[ \frac{1}{N}\sum_{\it R }
A~Z({\it R }) \log A~Z({\it R })\right] \label{eq:HI} \end{equation}

to a given order in $\epsilon$.

\begin{equation} Z({\it R })^{(1)} = e^{NK}e^{-2K} \exp \left( J \sum_{i=1}^N
r_{i+1} r_i \right) \sum_{j=1}^N \exp [-2J r_j(r_{j-1}+r_{j+1})]
\label{eq:Z1} \end{equation}

To the second
class, $b$, belong those configurations in which the two flipped
spins are {\it not} neighbors - there are $N(N-3)/2$ such terms in
the sum (\ref{eq:ZR}), and the respective contributions
are\footnote{ We use the obvious identifications imposed by
periodic boundary conditions, e.g. $r_{N+1}=r_1,~~r_{N+2}=r_2$} 
\begin{equation} Z({\it R })^{(2a)} = e^{NK}e^{-4K} \exp \left( J \sum_{i=1}^N
r_{i+1} r_i \right) \sum_{j=1}^N \exp [-2J
(r_jr_{j-1}+r_{j+1}r_{j+2})] \label{eq:Z2a} \end{equation} 
\begin{equation} Z({\it R })^{(2b)} = e^{NK}e^{-4K} \exp \left( J \sum_{i=1}^N
r_{i+1} r_i \right) \frac{1}{2}\sum_{j=1}^N \sum_{k \neq j,j\pm1}
\exp [-2J r_j(r_{j-1}+r_{j+1}) - 2J r_k(r_{k-1}+r_{k+1})]
\label{eq:Z2b} \end{equation}

\begin{equation} Z({\it R })^{(2a)} = e^{NK}e^{-4K} \exp \left( J \sum_{i=1}^N
r_{i+1} r_i \right) \sum_{j=1}^N \exp [-2J
(r_jr_{j-1}+r_{j+1}r_{j+2})] \label{eq:Z2a} \end{equation}

\begin{equation} Z({\it R })^{(2b)} = e^{NK}e^{-4K} \exp \left( J \sum_{i=1}^N
r_{i+1} r_i \right) \frac{1}{2}\sum_{j=1}^N \sum_{k \neq j,j\pm1}
\exp [-2J r_j(r_{j-1}+r_{j+1}) - 2J r_k(r_{k-1}+r_{k+1})]
\label{eq:Z2b} \end{equation}

\begin{equation} \sum_R e^{{\cal H}(R)} \qquad  {\rm where} \qquad {\cal
H}(R)=\sum_j \Delta_j J r_j r_{j+1} \qquad {\rm with} \qquad
\Delta_j=\pm 1 \end{equation}

\noindent Moreover, according to \cite{Cover}, $C_N \geq H$, and the
convergence is monotone : \begin{equation} C_N \searrow H \quad (N \to \infty)
\end{equation}

For this, we represent $Z$ using the
original variables $p, {\epsilon }$ (note that from this point of we work
with open boundary conditions on the Ising chain of $N$ spins):

\begin{equation} Z(R) = \sum_S (1-p)^{\sum_{i=1}^{N-1} 1_{S_i = S_{i+1}}}
p^{N-1-\sum_{i=1}^{N-1} 1_{S_i = S_{i+1}}} (1-{\epsilon })^{\sum_{i=1}^N
1_{S_i = R_i}}  {\epsilon }^{N-\sum_{i=1}^n 1_{S_i = R_i}}
\label{prob_R_cs_style} \end{equation}
 \noindent where we denote $1_{s,s'}=(1+s s')/2$.

\begin{equation} Z(R) = \sum_S (1-p)^{\sum_{i=1}^{N-1} 1_{S_i = S_{i+1}}}
p^{N-1-\sum_{i=1}^{N-1} 1_{S_i = S_{i+1}}} (1-{\epsilon })^{\sum_{i=1}^N
1_{S_i = R_i}}  {\epsilon }^{N-\sum_{i=1}^n 1_{S_i = R_i}}
\label{prob_R_cs_style} \end{equation}

\begin{equation} H_N = -\sum_{R} \left[ \sum_{i=0}^N Z_{i} (R) {\epsilon }^i \right]
\Biggl[ \log Z_0(R) - \Biggr. \left. \sum_{j=1}^k \frac{
(-\sum_{i=1}^n Z_{i} (R) {\epsilon }^i)^j }{j Z_0 (R)^j} \right] +
O({\epsilon }^{k+1}) \end{equation}

\noindent When extended to terms of order $\epsilon^k$, this equation
gives us precisely the expansion of the upper-bound $C_N$ up to the
{\it k-th} order,
 \begin{equation}
 C_N = \sum_{i=0}^{k} C_N^{(i)}{\epsilon }^i + O({\epsilon }^{k+1})
  \end{equation}
